Ext.ns('Ext.ux.form');

/**
 * @class Ext.ux.form.MultiSelect
 * @extends Ext.form.Field
 * A control that allows selection and form submission of multiple list items.
 *
 *  @history
 *    2008-06-19 bpm Original code contributed by Toby Stuart (with contributions from Robert Williams)
 *    2008-06-19 bpm Docs and demo code clean up
 *
 * @constructor
 * Create a new MultiSelect
 * @param {Object} config Configuration options
 * @xtype multiselect 
 */
Ext.ux.form.MultiSelect = Ext.extend(Ext.form.Field,  {
    /**
     * @cfg {String} legend Wraps the object with a fieldset and specified legend.
     */
    /**
     * @cfg {Ext.ListView} view The {@link Ext.ListView} used to render the multiselect list.
     */
    /**
     * @cfg {String/Array} dragGroup The ddgroup name(s) for the MultiSelect DragZone (defaults to undefined).
     */
    /**
     * @cfg {String/Array} dropGroup The ddgroup name(s) for the MultiSelect DropZone (defaults to undefined).
     */
    /**
     * @cfg {Boolean} ddReorder Whether the items in the MultiSelect list are drag/drop reorderable (defaults to false).
     */
    ddReorder:false,
    /**
     * @cfg {Object/Array} tbar The top toolbar of the control. This can be a {@link Ext.Toolbar} object, a
     * toolbar config, or an array of buttons/button configs to be added to the toolbar.
     */
    /**
     * @cfg {String} appendOnly True if the list should only allow append drops when drag/drop is enabled
     * (use for lists which are sorted, defaults to false).
     */
    appendOnly:false,
    /**
     * @cfg {Number} width Width in pixels of the control (defaults to 100).
     */
    width:100,
    /**
     * @cfg {Number} height Height in pixels of the control (defaults to 100).
     */
    height:100,
    /**
     * @cfg {String/Number} displayField Name/Index of the desired display field in the dataset (defaults to 0).
     */
    displayField:0,
    /**
     * @cfg {String/Number} valueField Name/Index of the desired value field in the dataset (defaults to 1).
     */
    valueField:1,
    /**
     * @cfg {Boolean} allowBlank False to require at least one item in the list to be selected, true to allow no
     * selection (defaults to true).
     */
    allowBlank:true,
    /**
     * @cfg {Number} minSelections Minimum number of selections allowed (defaults to 0).
     */
    minSelections:0,
    /**
     * @cfg {Number} maxSelections Maximum number of selections allowed (defaults to Number.MAX_VALUE).
     */
    maxSelections:Number.MAX_VALUE,
    /**
     * @cfg {String} blankText Default text displayed when the control contains no items (defaults to the same value as
     * {@link Ext.form.TextField#blankText}.
     */
    blankText:Ext.form.TextField.prototype.blankText,
    /**
     * @cfg {String} minSelectionsText Validation message displayed when {@link #minSelections} is not met (defaults to 'Minimum {0}
     * item(s) required').  The {0} token will be replaced by the value of {@link #minSelections}.
     */
    minSelectionsText:'Minimum {0} item(s) required',
    /**
     * @cfg {String} maxSelectionsText Validation message displayed when {@link #maxSelections} is not met (defaults to 'Maximum {0}
     * item(s) allowed').  The {0} token will be replaced by the value of {@link #maxSelections}.
     */
    maxSelectionsText:'Maximum {0} item(s) allowed',
    /**
     * @cfg {String} delimiter The string used to delimit between items when set or returned as a string of values
     * (defaults to ',').
     */
    delimiter:',',
    /**
     * @cfg {Ext.data.Store/Array} store The data source to which this MultiSelect is bound (defaults to <tt>undefined</tt>).
     * Acceptable values for this property are:
     * <div class="mdetail-params"><ul>
     * <li><b>any {@link Ext.data.Store Store} subclass</b></li>
     * <li><b>an Array</b> : Arrays will be converted to a {@link Ext.data.ArrayStore} internally.
     * <div class="mdetail-params"><ul>
     * <li><b>1-dimensional array</b> : (e.g., <tt>['Foo','Bar']</tt>)<div class="sub-desc">
     * A 1-dimensional array will automatically be expanded (each array item will be the combo
     * {@link #valueField value} and {@link #displayField text})</div></li>
     * <li><b>2-dimensional array</b> : (e.g., <tt>[['f','Foo'],['b','Bar']]</tt>)<div class="sub-desc">
     * For a multi-dimensional array, the value in index 0 of each item will be assumed to be the combo
     * {@link #valueField value}, while the value at index 1 is assumed to be the combo {@link #displayField text}.
     * </div></li></ul></div></li></ul></div>
     */

    // private
    defaultAutoCreate : {tag: "div"},

    // private
    initComponent: function(){
        Ext.ux.form.MultiSelect.superclass.initComponent.call(this);

        if(Ext.isArray(this.store)){
            if (Ext.isArray(this.store[0])){
                this.store = new Ext.data.ArrayStore({
                    fields: ['value','text'],
                    data: this.store
                });
                this.valueField = 'value';
            }else{
                this.store = new Ext.data.ArrayStore({
                    fields: ['text'],
                    data: this.store,
                    expandData: true
                });
                this.valueField = 'text';
            }
            this.displayField = 'text';
        } else {
            this.store = Ext.StoreMgr.lookup(this.store);
        }

        this.addEvents({
            'dblclick' : true,
            'click' : true,
            'change' : true,
            'drop' : true
        });
    },

    // private
    onRender: function(ct, position){
        Ext.ux.form.MultiSelect.superclass.onRender.call(this, ct, position);

        var fs = this.fs = new Ext.form.FieldSet({
            renderTo: this.el,
            title: this.legend,
            height: this.height,
            width: this.width,
            style: "padding:0;",
            tbar: this.tbar,
            bodyStyle: 'overflow: auto;'
        });

        this.view = new Ext.ListView({
            multiSelect: true,
            store: this.store,
            columns: [{ header: 'Value', width: 1, dataIndex: this.displayField }],
            hideHeaders: true
        });

        fs.add(this.view);

        this.view.on('click', this.onViewClick, this);
        this.view.on('beforeclick', this.onViewBeforeClick, this);
        this.view.on('dblclick', this.onViewDblClick, this);

        this.hiddenName = this.name || Ext.id();
        var hiddenTag = { tag: "input", type: "hidden", value: "", name: this.hiddenName };
        this.hiddenField = this.el.createChild(hiddenTag);
        this.hiddenField.dom.disabled = this.hiddenName != this.name;
        fs.doLayout();
    },

    // private
    afterRender: function(){
        Ext.ux.form.MultiSelect.superclass.afterRender.call(this);

        if (this.ddReorder && !this.dragGroup && !this.dropGroup){
            this.dragGroup = this.dropGroup = 'MultiselectDD-' + Ext.id();
        }

        if (this.draggable || this.dragGroup){
            this.dragZone = new Ext.ux.form.MultiSelect.DragZone(this, {
                ddGroup: this.dragGroup
            });
        }
        if (this.droppable || this.dropGroup){
            this.dropZone = new Ext.ux.form.MultiSelect.DropZone(this, {
                ddGroup: this.dropGroup
            });
        }
    },

    // private
    onViewClick: function(vw, index, node, e) {
        this.fireEvent('change', this, this.getValue(), this.hiddenField.dom.value);
        this.hiddenField.dom.value = this.getValue();
        this.fireEvent('click', this, e);
        this.validate();
    },

    // private
    onViewBeforeClick: function(vw, index, node, e) {
        if (this.disabled) {return false;}
    },

    // private
    onViewDblClick : function(vw, index, node, e) {
        return this.fireEvent('dblclick', vw, index, node, e);
    },

    /**
     * Returns an array of data values for the selected items in the list. The values will be separated
     * by {@link #delimiter}.
     * @return {Array} value An array of string data values
     */
    getValue: function(valueField){        
        var returnArray = [];
        var selectionsArray = this.view.getSelectedIndexes();
        if (selectionsArray.length == 0) {return '';}
        for (var i=0; i<selectionsArray.length; i++) {
            //alert(this.store.getAt(selectionsArray[i]).get('ProductionStatusId'));
             //returnArray.push(this.store.getAt(selectionsArray[i]).get('ProductionStatusId'));

            try{
                returnArray.push(this.store.getAt(selectionsArray[i]).get((valueField != null) ? valueField : this.valueField));
            }catch(e){
                //log(selectionsArray[i]);
            }
        }
        return returnArray.join(this.delimiter);
    },

    /**
     * Sets a delimited string (using {@link #delimiter}) or array of data values into the list.
     * @param {String/Array} values The values to set
     */
    setValue: function(values) {
        var index;
        var selections = [];
        this.view.clearSelections();
        this.hiddenField.dom.value = '';

        if (!values || (values == '')) { return; }

        if (!Ext.isArray(values)) { values = values.split(this.delimiter); }
        for (var i=0; i<values.length; i++) {
            index = this.view.store.indexOf(this.view.store.query(this.valueField,
                new RegExp('^' + values[i] + '$', "i")).itemAt(0));
            selections.push(index);
        }
        this.view.select(selections);
        this.hiddenField.dom.value = this.getValue();
        this.validate();
    },

    // inherit docs
    reset : function() {
        this.setValue('');
    },

    // inherit docs
    getRawValue: function(valueField) {
        var tmp = this.getValue(valueField);
        if (tmp.length) {
            tmp = tmp.split(this.delimiter);
        }
        else {
            tmp = [];
        }
        return tmp;
    },

    // inherit docs
    setRawValue: function(values){
        setValue(values);
    },

    // inherit docs
    validateValue : function(value){
        if (value.length < 1) { // if it has no value
             if (this.allowBlank) {
                 this.clearInvalid();
                 return true;
             } else {
                 this.markInvalid(this.blankText);
                 return false;
             }
        }
        if (value.length < this.minSelections) {
            this.markInvalid(String.format(this.minSelectionsText, this.minSelections));
            return false;
        }
        if (value.length > this.maxSelections) {
            this.markInvalid(String.format(this.maxSelectionsText, this.maxSelections));
            return false;
        }
        return true;
    },

    // inherit docs
    disable: function(){
        this.disabled = true;
        this.hiddenField.dom.disabled = true;
        this.fs.disable();
    },

    // inherit docs
    enable: function(){
        this.disabled = false;
        this.hiddenField.dom.disabled = false;
        this.fs.enable();
    },

    // inherit docs
    destroy: function(){
        Ext.destroy(this.fs, this.dragZone, this.dropZone);
        Ext.ux.form.MultiSelect.superclass.destroy.call(this);
    }
});


Ext.reg('multiselect', Ext.ux.form.MultiSelect);

//backwards compat
Ext.ux.Multiselect = Ext.ux.form.MultiSelect;


Ext.ux.form.MultiSelect.DragZone = function(ms, config){
    this.ms = ms;
    this.view = ms.view;
    var ddGroup = config.ddGroup || 'MultiselectDD';
    var dd;
    if (Ext.isArray(ddGroup)){
        dd = ddGroup.shift();
    } else {
        dd = ddGroup;
        ddGroup = null;
    }
    Ext.ux.form.MultiSelect.DragZone.superclass.constructor.call(this, this.ms.fs.body, { containerScroll: true, ddGroup: dd });
    this.setDraggable(ddGroup);
};

Ext.extend(Ext.ux.form.MultiSelect.DragZone, Ext.dd.DragZone, {
    onInitDrag : function(x, y){
        var el = Ext.get(this.dragData.ddel.cloneNode(true));
        this.proxy.update(el.dom);
        el.setWidth(el.child('em').getWidth());
        this.onStartDrag(x, y);
        return true;
    },
    
    // private
    collectSelection: function(data) {
        data.repairXY = Ext.fly(this.view.getSelectedNodes()[0]).getXY();
        var i = 0;
        this.view.store.each(function(rec){
            if (this.view.isSelected(i)) {
                var n = this.view.getNode(i);
                var dragNode = n.cloneNode(true);
                dragNode.id = Ext.id();
                data.ddel.appendChild(dragNode);
                data.records.push(this.view.store.getAt(i));
                data.viewNodes.push(n);
            }
            i++;
        }, this);
    },

    // override
    onEndDrag: function(data, e) {
        var d = Ext.get(this.dragData.ddel);
        if (d && d.hasClass("multi-proxy")) {
            d.remove();
        }
    },

    // override
    getDragData: function(e){
        var target = this.view.findItemFromChild(e.getTarget());
        if(target) {
            if (!this.view.isSelected(target) && !e.ctrlKey && !e.shiftKey) {
                this.view.select(target);
                this.ms.setValue(this.ms.getValue());
            }
            if (this.view.getSelectionCount() == 0 || e.ctrlKey || e.shiftKey) return false;
            var dragData = {
                sourceView: this.view,
                viewNodes: [],
                records: []
            };
            if (this.view.getSelectionCount() == 1) {
                var i = this.view.getSelectedIndexes()[0];
                var n = this.view.getNode(i);
                dragData.viewNodes.push(dragData.ddel = n);
                dragData.records.push(this.view.store.getAt(i));
                dragData.repairXY = Ext.fly(n).getXY();
            } else {
                dragData.ddel = document.createElement('div');
                dragData.ddel.className = 'multi-proxy';
                this.collectSelection(dragData);
            }
            return dragData;
        }
        return false;
    },

    // override the default repairXY.
    getRepairXY : function(e){
        return this.dragData.repairXY;
    },

    // private
    setDraggable: function(ddGroup){
        if (!ddGroup) return;
        if (Ext.isArray(ddGroup)) {
            Ext.each(ddGroup, this.setDraggable, this);
            return;
        }
        this.addToGroup(ddGroup);
    }
});

Ext.ux.form.MultiSelect.DropZone = function(ms, config){
    this.ms = ms;
    this.view = ms.view;
    var ddGroup = config.ddGroup || 'MultiselectDD';
    var dd;
    if (Ext.isArray(ddGroup)){
        dd = ddGroup.shift();
    } else {
        dd = ddGroup;
        ddGroup = null;
    }
    Ext.ux.form.MultiSelect.DropZone.superclass.constructor.call(this, this.ms.fs.body, { containerScroll: true, ddGroup: dd });
    this.setDroppable(ddGroup);
};

Ext.extend(Ext.ux.form.MultiSelect.DropZone, Ext.dd.DropZone, {
    /**
	 * Part of the Ext.dd.DropZone interface. If no target node is found, the
	 * whole Element becomes the target, and this causes the drop gesture to append.
	 */
    getTargetFromEvent : function(e) {
        var target = e.getTarget();
        return target;
    },

    // private
    getDropPoint : function(e, n, dd){
        if (n == this.ms.fs.body.dom) { return "below"; }
        var t = Ext.lib.Dom.getY(n), b = t + n.offsetHeight;
        var c = t + (b - t) / 2;
        var y = Ext.lib.Event.getPageY(e);
        if(y <= c) {
            return "above";
        }else{
            return "below";
        }
    },

    // private
    isValidDropPoint: function(pt, n, data) {
        if (!data.viewNodes || (data.viewNodes.length != 1)) {
            return true;
        }
        var d = data.viewNodes[0];
        if (d == n) {
            return false;
        }
        if ((pt == "below") && (n.nextSibling == d)) {
            return false;
        }
        if ((pt == "above") && (n.previousSibling == d)) {
            return false;
        }
        return true;
    },

    // override
    onNodeEnter : function(n, dd, e, data){
        return false;
    },

    // override
    onNodeOver : function(n, dd, e, data){
        var dragElClass = this.dropNotAllowed;
        var pt = this.getDropPoint(e, n, dd);
        if (this.isValidDropPoint(pt, n, data)) {
            if (this.ms.appendOnly) {
                return "x-tree-drop-ok-below";
            }

            // set the insert point style on the target node
            if (pt) {
                var targetElClass;
                if (pt == "above"){
                    dragElClass = n.previousSibling ? "x-tree-drop-ok-between" : "x-tree-drop-ok-above";
                    targetElClass = "x-view-drag-insert-above";
                } else {
                    dragElClass = n.nextSibling ? "x-tree-drop-ok-between" : "x-tree-drop-ok-below";
                    targetElClass = "x-view-drag-insert-below";
                }
                if (this.lastInsertClass != targetElClass){
                    Ext.fly(n).replaceClass(this.lastInsertClass, targetElClass);
                    this.lastInsertClass = targetElClass;
                }
            }
        }
        return dragElClass;
    },

    // private
    onNodeOut : function(n, dd, e, data){
        this.removeDropIndicators(n);
    },

    // private
    onNodeDrop : function(n, dd, e, data){
        if (this.ms.fireEvent("drop", this, n, dd, e, data) === false) {
            return false;
        }
        var pt = this.getDropPoint(e, n, dd);
        if (n != this.ms.fs.body.dom)
            n = this.view.findItemFromChild(n);
        var insertAt = (this.ms.appendOnly || (n == this.ms.fs.body.dom)) ? this.view.store.getCount() : this.view.indexOf(n);
        if (pt == "below") {
            insertAt++;
        }

        var dir = false;

        // Validate if dragging within the same MultiSelect
        if (data.sourceView == this.view) {
            // If the first element to be inserted below is the target node, remove it
            if (pt == "below") {
                if (data.viewNodes[0] == n) {
                    data.viewNodes.shift();
                }
            } else {  // If the last element to be inserted above is the target node, remove it
                if (data.viewNodes[data.viewNodes.length - 1] == n) {
                    data.viewNodes.pop();
                }
            }

            // Nothing to drop...
            if (!data.viewNodes.length) {
                return false;
            }

            // If we are moving DOWN, then because a store.remove() takes place first,
            // the insertAt must be decremented.
            if (insertAt > this.view.store.indexOf(data.records[0])) {
                dir = 'down';
                insertAt--;
            }
        }

        for (var i = 0; i < data.records.length; i++) {
            var r = data.records[i];
            if (data.sourceView) {
                data.sourceView.store.remove(r);
            }
            this.view.store.insert(dir == 'down' ? insertAt : insertAt++, r);
            var si = this.view.store.sortInfo;
            if(si){
                this.view.store.sort(si.field, si.direction);
            }
        }
        return true;
    },

    // private
    removeDropIndicators : function(n){
        if(n){
            Ext.fly(n).removeClass([
                "x-view-drag-insert-above",
                "x-view-drag-insert-left",
                "x-view-drag-insert-right",
                "x-view-drag-insert-below"]);
            this.lastInsertClass = "_noclass";
        }
    },

    // private
    setDroppable: function(ddGroup){
        if (!ddGroup) return;
        if (Ext.isArray(ddGroup)) {
            Ext.each(ddGroup, this.setDroppable, this);
            return;
        }
        this.addToGroup(ddGroup);
    }
});
Ext.ns('Ext.ux.form');

/**
 * Creates new DateTime
 * @constructor
 * @param {Object} config A config object
 */
Ext.ux.form.DateTime = Ext.extend(Ext.form.Field, {
        
/**
         * @cfg {String/Object} defaultAutoCreate DomHelper element spec
         * Let superclass to create hidden field instead of textbox. Hidden will be submittend to server
         */
         defaultAutoCreate:{tag:'input', type:'hidden'}
        
/**
         * @cfg {Number} timeWidth Width of time field in pixels (defaults to 100)
         */
        ,timeWidth:100
        
/**
         * @cfg {String} dtSeparator Date - Time separator. Used to split date and time (defaults to ' ' (space))
         */
        ,dtSeparator:' '
        
/**
         * @cfg {String} hiddenFormat Format of datetime used to store value in hidden field
         * and submitted to server (defaults to 'Y-m-d H:i:s' that is mysql format)
         */
        ,hiddenFormat:'Y-m-d H:i:s'
        
/**
         * @cfg {Boolean} otherToNow Set other field to now() if not explicly filled in (defaults to true)
         */
        ,otherToNow:true
        
/**
         * @cfg {Boolean} emptyToNow Set field value to now on attempt to set empty value.
         * If it is true then setValue() sets value of field to current date and time (defaults to false)
         */
        
/**
         * @cfg {String} timePosition Where the time field should be rendered. 'right' is suitable for forms
         * and 'below' is suitable if the field is used as the grid editor (defaults to 'right')
         */
        ,timePosition:'right' // valid values:'below', 'right'
        
/**
         * @cfg {String} dateFormat Format of DateField. Can be localized. (defaults to 'm/y/d')
         */
        ,dateFormat:'m/d/y'
        
/**
         * @cfg {String} timeFormat Format of TimeField. Can be localized. (defaults to 'g:i A')
         */
        ,timeFormat:'g:i A'
        
/**
         * @cfg {Object} dateConfig Config for DateField constructor.
         */
        
/**
         * @cfg {Object} timeConfig Config for TimeField constructor.
         */

        // {{{
        /**
         * @private
         * creates DateField and TimeField and installs the necessary event handlers
         */
        ,initComponent:function() {
                // call parent initComponent
                Ext.ux.form.DateTime.superclass.initComponent.call(this);

                // create DateField
                var dateConfig = Ext.apply({}, {
                         id:this.id + '-date'
                        ,format:this.dateFormat || Ext.form.DateField.prototype.format
                        ,width:this.timeWidth
                        ,selectOnFocus:this.selectOnFocus
                        ,listeners:{
                                  blur:{scope:this, fn:this.onBlur}
                                 ,focus:{scope:this, fn:this.onFocus}
                        }
                }, this.dateConfig);
                this.df = new Ext.form.DateField(dateConfig);
                this.df.ownerCt = this;
                delete(this.dateFormat);

                // create TimeField
                var timeConfig = Ext.apply({}, {
                         id:this.id + '-time'
                        ,format:this.timeFormat || Ext.form.TimeField.prototype.format
                        ,width:this.timeWidth
                        ,selectOnFocus:this.selectOnFocus
                        ,listeners:{
                                  blur:{scope:this, fn:this.onBlur}
                                 ,focus:{scope:this, fn:this.onFocus}
                        }
                }, this.timeConfig);
                this.tf = new Ext.form.TimeField(timeConfig);
                this.tf.ownerCt = this;
                delete(this.timeFormat);

                // relay events
                this.relayEvents(this.df, ['focus', 'specialkey', 'invalid', 'valid']);
                this.relayEvents(this.tf, ['focus', 'specialkey', 'invalid', 'valid']);

        } // eo function initComponent
        // }}}
        // {{{
        /**
         * @private
         * Renders underlying DateField and TimeField and provides a workaround for side error icon bug
         */
        ,onRender:function(ct, position) {
                // don't run more than once
                if(this.isRendered) {
                        return;
                }

                // render underlying hidden field
                Ext.ux.form.DateTime.superclass.onRender.call(this, ct, position);

                // render DateField and TimeField
                // create bounding table
                var t;
                if('below' === this.timePosition || 'bellow' === this.timePosition) {
                        t = Ext.DomHelper.append(ct, {tag:'table',style:'border-collapse:collapse',children:[
                                 {tag:'tr',children:[{tag:'td', style:'padding-bottom:1px', cls:'ux-datetime-date'}]}
                                ,{tag:'tr',children:[{tag:'td', cls:'ux-datetime-time'}]}
                        ]}, true);
                }
                else {
                        t = Ext.DomHelper.append(ct, {tag:'table',style:'border-collapse:collapse',children:[
                                {tag:'tr',children:[
                                        {tag:'td',style:'padding-right:4px', cls:'ux-datetime-date'},{tag:'td', cls:'ux-datetime-time'}
                                ]}
                        ]}, true);
                }

                this.tableEl = t;
                this.wrap = t.wrap({cls:'x-form-field-wrap'});
//              this.wrap = t.wrap();
        this.wrap.on("mousedown", this.onMouseDown, this, {delay:10});

                // render DateField & TimeField
                this.df.render(t.child('td.ux-datetime-date'));
                this.tf.render(t.child('td.ux-datetime-time'));

                // workaround for IE trigger misalignment bug
                if(Ext.isIE && Ext.isStrict) {
                        t.select('input').applyStyles({top:0});
                }

                this.on('specialkey', this.onSpecialKey, this);
                this.df.el.swallowEvent(['keydown', 'keypress']);
                this.tf.el.swallowEvent(['keydown', 'keypress']);

                // create icon for side invalid errorIcon
                if('side' === this.msgTarget) {
                        var elp = this.el.findParent('.x-form-element', 10, true);
                        this.errorIcon = elp.createChild({cls:'x-form-invalid-icon'});

                        this.df.errorIcon = this.errorIcon;
                        this.tf.errorIcon = this.errorIcon;
                }

                // setup name for submit
                this.el.dom.name = this.hiddenName || this.name || this.id;

                // prevent helper fields from being submitted
                this.df.el.dom.removeAttribute("name");
                this.tf.el.dom.removeAttribute("name");

                // we're rendered flag
                this.isRendered = true;

                // update hidden field
                this.updateHidden();

        } // eo function onRender
        // }}}
        // {{{
        /**
         * @private
         */
    ,adjustSize:Ext.BoxComponent.prototype.adjustSize
        // }}}
        // {{{
        /**
         * @private
         */
        ,alignErrorIcon:function() {
        this.errorIcon.alignTo(this.tableEl, 'tl-tr', [2, 0]);
        }
        // }}}
        // {{{
        /**
         * @private initializes internal dateValue
         */
        ,initDateValue:function() {
                this.dateValue = this.otherToNow ? new Date() : new Date(1970, 0, 1, 0, 0, 0);
        }
        // }}}
        // {{{
    
/**
     * Calls clearInvalid on the DateField and TimeField
     */
    ,clearInvalid:function(){
        this.df.clearInvalid();
        this.tf.clearInvalid();
    } // eo function clearInvalid
    // }}}
        // {{{
    
/**
     * Calls markInvalid on both DateField and TimeField
         * @param {String} msg Invalid message to display
     */
    ,markInvalid:function(msg){
        this.df.markInvalid(msg);
        this.tf.markInvalid(msg);
    } // eo function markInvalid
    // }}}
        // {{{
        /**
         * @private
         * called from Component::destroy. 
         * Destroys all elements and removes all listeners we've created.
         */
        ,beforeDestroy:function() {
                if(this.isRendered) {
//                      this.removeAllListeners();
                        this.wrap.removeAllListeners();
                        this.wrap.remove();
                        this.tableEl.remove();
                        this.df.destroy();
                        this.tf.destroy();
                }
        } // eo function beforeDestroy
        // }}}
        // {{{
    
/**
     * Disable this component.
     * @return {Ext.Component} this
     */
    ,disable:function() {
                if(this.isRendered) {
                        this.df.disabled = this.disabled;
                        this.df.onDisable();
                        this.tf.onDisable();
                }
                this.disabled = true;
                this.df.disabled = true;
                this.tf.disabled = true;
        this.fireEvent("disable", this);
        return this;
    } // eo function disable
        // }}}
        // {{{
    
/**
     * Enable this component.
     * @return {Ext.Component} this
     */
    ,enable:function() {
        if(this.rendered){
                        this.df.onEnable();
                        this.tf.onEnable();
        }
        this.disabled = false;
                this.df.disabled = false;
                this.tf.disabled = false;
        this.fireEvent("enable", this);
        return this;
    } // eo function enable
        // }}}
        // {{{
        /**
         * @private Focus date filed
         */
        ,focus:function() {
                this.df.focus();
        } // eo function focus
        // }}}
        // {{{
        /**
         * @private
         */
        ,getPositionEl:function() {
                return this.wrap;
        }
        // }}}
        // {{{
        /**
         * @private
         */
        ,getResizeEl:function() {
                return this.wrap;
        }
        // }}}
        // {{{
        
/**
         * @return {Date/String} Returns value of this field
         */
        ,getValue:function() {
                // create new instance of date
                return this.dateValue ? new Date(this.dateValue) : '';
        } // eo function getValue
        // }}}
        // {{{
        /**
         * @return {Boolean} true = valid, false = invalid
         * @private Calls isValid methods of underlying DateField and TimeField and returns the result
         */
        ,isValid:function() {
                return this.df.isValid() && this.tf.isValid();
        } // eo function isValid
        // }}}
    // {{{
    
/**
     * Returns true if this component is visible
     * @return {boolean} 
     */
    ,isVisible : function(){
        return this.df.rendered && this.df.getActionEl().isVisible();
    } // eo function isVisible
        // }}}
        // {{{
        /** 
         * @private Handles blur event
         */
        ,onBlur:function(f) {
                // called by both DateField and TimeField blur events

                // revert focus to previous field if clicked in between
                if(this.wrapClick) {
                        f.focus();
                        this.wrapClick = false;
                }

                // update underlying value
                if(f === this.df) {
                        this.updateDate();
                }
                else {
                        this.updateTime();
                }
                this.updateHidden();

                // fire events later
                (function() {
                        if(!this.df.hasFocus && !this.tf.hasFocus) {
                                var v = this.getValue();
                                if(String(v) !== String(this.startValue)) {
                                        this.fireEvent("change", this, v, this.startValue);
                                }
                                this.hasFocus = false;
                                this.fireEvent('blur', this);
                        }
                }).defer(100, this);

        } // eo function onBlur
        // }}}
        // {{{
        /**
         * @private Handles focus event
         */
        ,onFocus:function() {
        if(!this.hasFocus){
            this.hasFocus = true;
            this.startValue = this.getValue();
            this.fireEvent("focus", this);
        }
        }
        // }}}
        // {{{
        /**
         * @private Just to prevent blur event when clicked in the middle of fields
         */
        ,onMouseDown:function(e) {
                if(!this.disabled) {
                        this.wrapClick = 'td' === e.target.nodeName.toLowerCase();
                }
        }
        // }}}
        // {{{
        /**
         * @private
         * Handles Tab and Shift-Tab events
         */
        ,onSpecialKey:function(t, e) {
                var key = e.getKey();
                if(key === e.TAB) {
                        if(t === this.df && !e.shiftKey) {
                                e.stopEvent();
                                this.tf.focus();
                        }
                        if(t === this.tf && e.shiftKey) {
                                e.stopEvent();
                                this.df.focus();
                        }
                }
                // otherwise it misbehaves in editor grid
                if(key === e.ENTER) {
                        this.updateValue();
                }

        } // eo function onSpecialKey
        // }}}
        // {{{
        /**
         * @private Sets the value of DateField
         */
        ,setDate:function(date) {
                this.df.setValue(date);
        } // eo function setDate
        // }}}
        // {{{
        /** 
         * @private Sets the value of TimeField
         */
        ,setTime:function(date) {
                this.tf.setValue(date);
        } // eo function setTime
        // }}}
        // {{{
        /**
         * @private
         * Sets correct sizes of underlying DateField and TimeField
         * With workarounds for IE bugs
         */
        ,setSize:function(w, h) {
                if(!w) {
                        return;
                }
                if('below' === this.timePosition) {
                        this.df.setSize(w, h);
                        this.tf.setSize(w, h);
                        if(Ext.isIE) {
                                this.df.el.up('td').setWidth(w);
                                this.tf.el.up('td').setWidth(w);
                        }
                }
                else {
                        this.df.setSize(w - this.timeWidth - 4, h);
                        this.tf.setSize(this.timeWidth, h);

                        if(Ext.isIE) {
                                this.df.el.up('td').setWidth(w - this.timeWidth - 4);
                                this.tf.el.up('td').setWidth(this.timeWidth);
                        }
                }
        } // eo function setSize
        // }}}
        // {{{
        
/**
         * @param {Mixed} val Value to set
         * Sets the value of this field
         */
        ,setValue:function(val) {
                if(!val && true === this.emptyToNow) {
                        this.setValue(new Date());
                        return;
                }
                else if(!val) {
                        this.setDate('');
                        this.setTime('');
                        this.updateValue();
                        return;
                }
        if ('number' === typeof val) {
          val = new Date(val);
        }
        else if('string' === typeof val && this.hiddenFormat) {
                        val = Date.parseDate(val, this.hiddenFormat)
        }
                val = val ? val : new Date(1970, 0 ,1, 0, 0, 0);
                var da, time;
                if(val instanceof Date) {
                        this.setDate(val);
                        this.setTime(val);
                        this.dateValue = new Date(val);
                }
                else {
                        da = val.split(this.dtSeparator);
                        this.setDate(da[0]);
                        if(da[1]) {
                                if(da[2]) {
                                        // add am/pm part back to time
                                        da[1] += da[2];
                                }
                                this.setTime(da[1]);
                        }
                }
                this.updateValue();
        } // eo function setValue
        // }}}
        // {{{
        
/**
     * Hide or show this component by boolean
     * @return {Ext.Component} this
     */
    ,setVisible: function(visible){
        if(visible) {
            this.df.show();
            this.tf.show();
        }else{
            this.df.hide();
            this.tf.hide();
        }
        return this;
    } // eo function setVisible
    // }}}
        //{{{
        ,show:function() {
                return this.setVisible(true);
        } // eo function show
        //}}}
        //{{{
        ,hide:function() {
                return this.setVisible(false);
        } // eo function hide
        //}}}
        // {{{
        /**
         * @private Updates the date part
         */
        ,updateDate:function() {

                var d = this.df.getValue();
                if(d) {
                        if(!(this.dateValue instanceof Date)) {
                                this.initDateValue();
                                if(!this.tf.getValue()) {
                                        this.setTime(this.dateValue);
                                }
                        }
                        this.dateValue.setMonth(0); // because of leap years
                        this.dateValue.setFullYear(d.getFullYear());
                        this.dateValue.setMonth(d.getMonth(), d.getDate());
//                      this.dateValue.setDate(d.getDate());
                }
                else {
                        this.dateValue = '';
                        this.setTime('');
                }
        } // eo function updateDate
        // }}}
        // {{{
        /**
         * @private
         * Updates the time part
         */
        ,updateTime:function() {
                var t = this.tf.getValue();
                if(t && !(t instanceof Date)) {
                        t = Date.parseDate(t, this.tf.format);
                }
                if(t && !this.df.getValue()) {
                        this.initDateValue();
                        this.setDate(this.dateValue);
                }
                if(this.dateValue instanceof Date) {
                        if(t) {
                                this.dateValue.setHours(t.getHours());
                                this.dateValue.setMinutes(t.getMinutes());
                                this.dateValue.setSeconds(t.getSeconds());
                        }
                        else {
                                this.dateValue.setHours(0);
                                this.dateValue.setMinutes(0);
                                this.dateValue.setSeconds(0);
                        }
                }
        } // eo function updateTime
        // }}}
        // {{{
        /**
         * @private Updates the underlying hidden field value
         */
        ,updateHidden:function() {
                if(this.isRendered) {
                        var value = this.dateValue instanceof Date ? this.dateValue.format(this.hiddenFormat) : '';
                        this.el.dom.value = value;
                }
        }
        // }}}
        // {{{
        /**
         * @private Updates all of Date, Time and Hidden
         */
        ,updateValue:function() {

                this.updateDate();
                this.updateTime();
                this.updateHidden();

                return;
        } // eo function updateValue
        // }}}
        // {{{
        
/**
         * @return {Boolean} true = valid, false = invalid
         * calls validate methods of DateField and TimeField
         */
        ,validate:function() {
                return this.df.validate() && this.tf.validate();
        } // eo function validate
        // }}}
        // {{{
        
/**
         * Returns renderer suitable to render this field
         * @param {Object} Column model config
         */
        ,renderer: function(field) {
                var format = field.editor.dateFormat || Ext.ux.form.DateTime.prototype.dateFormat;
                format += ' ' + (field.editor.timeFormat || Ext.ux.form.DateTime.prototype.timeFormat);
                var renderer = function(val) {
                        var retval = Ext.util.Format.date(val, format);
                        return retval;
                };
                return renderer;
        } // eo function renderer
        // }}}

}); // eo extend

// register xtype
Ext.reg('xdatetime', Ext.ux.form.DateTime);

Ext.ns('Ext.ux.window'); 

/**
 * @class Ext.ux.window.MessageWindowGroup
 * @extends Ext.WindowGroup
 * An object that represents a group of {@link Ext.ux.window.MessageWindow} instances
 * and provides position management in addition to the standard Window Group features.
 * @constructor
 */
Ext.ux.window.MessageWindowGroup = function (config) {
    config = config || {};
    var mgr = new Ext.WindowGroup();
    mgr.positions = [];
    Ext.apply(mgr, config);
    return mgr;
};

/**
 * @class Ext.ux.window.MessageWindowMgr
 * @extends Ext.ux.window.MessageWindowGroup
 * The default global Message Window group that is available automatically.  To have
 * more than one group of Message Windows to utilize separate positioning in addition
 * to the standard Window Manager features create additional instances of 
 * {@link Ext.ux.window.MessageWindowGroup} as needed.
 * @singleton
 */
Ext.ux.window.MessageWindowMgr = Ext.ux.window.MessageWindowGroup(); 

/**
 * @class Ext.ux.window.MessageWindow
 * @extends Ext.Window
 * <p>If you are looking for a lightweight implementation of Toast or Notification windows this is
 * <b>NOT</b> the class you want.  This class builds upon the implementation by <i>Edouard Fattal</i>.
 * This class creates a specialized Window for notification messages and offers the following features:</p>
 * 
 * <br>Demo link: <a href="http://extjs-ux.org/repo/authors/mjlecomte/trunk/Ext/ux/window/msgWindow.html">here</a>
 * <br>Forum thread: <a href="http://extjs.com/forum/showthread.php?t=48135">here</a><br>
 * 
 * <b>Features:</b>
 * <ul>
 * <li>+ Message windows may be bound to any element through configuration.</li>
 * <li>+ A single Message Window may be reused or multiple Message Windows may be used simultaneously.</li>
 * <li>+ Message windows can be managed by groups.</li>
 * <li>+ Several configurable options.</li>
 * <li>++ By default, Message Window will not steal focus.</li>
 * </ul>
 * <br>
 * <b>Known issues/caveats/bugs/roadmap:</b>
 * <ul>
 * <li>+ config for custom showFx incomplete </li>
 * <li>+ vertical location of subsequent windows may overlap if height changes.</li>
 * <li>+ add config to limit drag options (for example lock x or y axis, etc.)</li>
 * </ul>
 * @author Michael LeComte (<a href="http://extjs.com/forum/member.php?u=6834">mjlecomte</a>), inspired by Ext.ux.Notification\ToastWindow (Edouard Fattal)
 * @license <a href="http://www.gnu.org/licenses/lgpl.html">LGPL 3.0</a>
 * @version 0.3 - April 20, 2009
 */
