    var creatMapRefererGrid = function (id) {
        var refId = arguments[0];
        var grid_title = 'Reference';
        var chk_model = new Ext.grid.CheckboxSelectionModel({
            multiSelect: true,
            checkOnly: true,
            listeners: {
                rowdeselect: function (sm,rowIndex,record) {
                    console.log(record);
                    var ind = sms_name.indexOf(record.get('reference_cl_id'));
                    if (ind > -1)
                        sms_name.splice(ind,1);
                    record.set('checked','false');
                },
                rowselect: function (sm,rowIndex,record) {
                    console.log(record);
                    var ind = sms_name.indexOf(record.get('reference_cl_id'));
                    if (ind == -1)
                        sms_name.push(record.get('reference_cl_id'));
                    record.set('checked','true');
                }
            }
        });
        var charge_store = chargeStore(refId);
        var charge_grid = new Ext.grid.GridPanel({
            store: charge_store,
            layout: 'fit',
            title: grid_title,
            autoScroll: true,
            height: 400,
            selModel: chk_model,
            view: new Ext.grid.GroupingView({
                deferEmptyText: false,
                emptyText: '<div class="grid-data-empty"><div data-icon="/" class="empty-grid-icon"></div><div class="empty-grid-headline"></div><div class="empty-grid-byline">There are no records to show you right now.</div></div>',
                forceFit: true,
                groupTextTpl: '{text} ({[values.rs.length]} {[values.rs.length > 1 ? "Items" : "Item"]})'
            }),
            id: 'gidRefsCharge',
            clicksToEdit: '2',
            columns: [chk_model,{
                    header: '',
                    hidden: true,
                    dataIndex: 'refrence_referers_id',
                    tooltip: 'Main Type'
                },
                {
                    header: 'Name',
                    sortable: true,
                    dataIndex: 'contactPerson',
                    tooltip: 'Name'
                },
                {
                    header: 'Mobile',
                    sortable: true,
                    dataIndex: 'contactNumber',
                    tooltip: 'Mobile'
                },
                {
                    header: 'Email',
                    sortable: true,
                    dataIndex: 'contactEmail',
                    tooltip: 'Email'
                }
            ],
            sm: chk_model,
            viewConfig: {
                forceFit: true
            },
            view: new Ext.grid.GroupingView({
                forceFit: true,
                showGroupName: false,
                enableNoGroups: false,
                enableGroupingMenu: false,
                hideGroupedColumn: false,
                deferEmptyText: false,
                getRowClass: function (record,index,params,store) {
                    switch (record.get('checkeds')) {
                        case '0':
                            return '';
                            break;
                        case '1':
                            return 'finascop_indicateColPINK';
                            break;
                    }

                },
                emptyText: '<div class="grid-data-empty"><div data-icon="" class="empty-grid-icon"></div><div class="empty-grid-headline"></div><div class="empty-grid-byline">There are no records to show you right now.</div></div>',
            }),
                    listeners: {
                        afterrender: function () {
                            {
                                var me = this;
                                charge_store.on('load',function () {
                                    var data = me.getStore().data.items;
                                    var recs = [];
                                    Ext.each(data,function (item,index) {
                                        if (item.data.checked == 1) {
                                            recs.push(index);
                                        }
                                    });
                                    me.getSelectionModel().selectRows(recs);
                                });
                            }
                        }
                    },
            stripeRows: true,
            autoExpandColumn: 'contactPerson'

        });
        return charge_grid;
    };
