    var createGroupTree = function () {
        var tree = new Ext.tree.TreePanel({
            region: 'center',
            title: 'Group',
            //iconCls: 'finascop_stockgroup',
            useArrows: true,
            autoScroll: true,
            layout: 'fit',
            height: winsize.height * 0.65,
            //autoHeight: true,
            width: 210,
            animate: true,
            enableDD: true,
            containerScroll: true,
            border: true,
            overClass: 'finascop_parent-group',
            itemSelector: 'finascop_child-group',
            dataUrl: modURL + '&op=getgroupitems',
            id: 'group_tree',
            mask: true,
            draggable: false,
            maskDisabled: false,
            maskConfig: {msg: "Loading items..."},
            root: {
                nodeType: 'async',
                text: 'GROUPS',
                draggable: false,
                id: 'root'
            },
            contextMenu: new Ext.menu.Menu({
                items: [{
                        id: 'edit-node',
                        text: 'Edit'
                    }],
                listeners: {
                    itemclick: function (item) {
                        switch (item.id)
                        {
                            case 'edit-node':
                                var n = item.parentMenu.contextNode;
                                if (n.parentNode)
                                {
                                    addOrEditGroup(n.id);
                                }
                                break;
                        }
                    },
                    load: function () {
                        setTimeout(function () {
                            if (WinMask)
                                WinMask.hide();
                        },500);
                    }
                }
            }),
            listeners: {
                contextmenu: function (node,e) {
//          Register the context node with the menu so that a Menu Item's handler function can access
//          it via its parentMenu property.
                    node.select();
                    var c = node.getOwnerTree().contextMenu;
                    c.contextNode = node;
                    c.showAt(e.getXY());
                }
            }
        });
        //Ext.getCmp('ldg_company').setValue(store.getAt('0').get('comp_id'));
        tree.getRootNode().expand();
        return tree;
    };

