    var ItemStoreToaddStock = function (fpod_id) {
        var partyStore = new Ext.data.JsonStore({
            autoLoad: true,
            id: 'pu_party_store',
            url: modURL + '&op=getItemStoreforStock',
            method: 'post',
            fields: ['item_id','item_name'],
            totalProperty: 'totalCount',
            root: 'data',
            listeners: {
                beforeload: function (store,opt) {
                    store.baseParams = {
                        fpod_id: fpod_id
                    };
                }
            }
        });
        return partyStore;
    };
