    var importCSV = function (branch,brName) {
        var win_csv = new Ext.Window({
            layout: 'fit',
            width: 400,
            autoHeight: true,
            border: false,
            title: 'Import Stock',
            icon: './resources/images/submenuicons/upload_fl.png',
            //iconCls: 'upload',
            shadow: false,
            floating: true,
            resizable: false,
            plain: true,
            constrain: true,
            draggable: true,
            items: [
                new Ext.form.FormPanel({
                    labelAlign: 'top',
                    labelSeparator: '',
                    bodyStyle: {
                        "background-color": "white",
                        "padding": "5px 5px 5px 10px"
                    },
                    autoHeight: true,
                    id: 'csv_form',
                    frame: false,
                    border: false,
                    fileUpload: true,
                    items: [
                        {
                            layout: 'form',
                            columnWidth: .3,
                            items: [{
                                    fieldLabel: 'Upload File (.csv)',
                                    labelAlign: 'top',
                                    xtype: 'fileuploadfield',
                                    accept: '.csv',
                                    id: 'excel_file',
                                    allowBlank: false,
                                    name: 'excel_file',
                                    tabIndex: 1,
                                    msgTarget: 'under',
                                    anchor: '98%',
                                    validator: function (v) {
                                        if (v != '') {
                                            //var exp = /^.*.(.xlsx|xlsm|xls|xltx|xltm|xlt|xml|xlam|xla|xlw|csv)$/;
                                            var exp = /^.*\.csv$/;
                                            if (!(exp.test(v))) {
                                                return 'Upload a valid CSV file.';
                                            }
                                            return true;
                                        }
                                        var filen = Ext.getCmp('excel_file').getValue();
                                        if (filen == '') {
                                            return 'Upload a file.';
                                        }
                                    }
                                }],
                            buttons: [
                                {
                                    iconCls: 'csv',
                                    text: 'Upload',
                                    handler: function () {
                                        var csv_form = Ext.getCmp('csv_form').getForm();
                                        var t = new Date();
                                        var t_stamp = t.format("YmdHis");
                                        if (csv_form.isValid()) {
                                            csv_form.submit({
                                                url: modURL + '&op=uploadStockcsvFile',
                                                waitTitle: 'Please Wait..',
                                                waitMsg: 'Saving data...',
                                                params: {
                                                    apikey: _SESSION.apikey,
                                                    tstamp: t_stamp,
                                                    branch: branch
                                                },
                                                success: function (csv_form,action) {
                                                    var result = Ext.decode(action.response.responseText);
                                                    console.log('result',result);
                                                    if (result.valid === true && result.success === true) {
                                                        win_csv.close();
                                                        Application.FstockUpload.dispalyUploadedStock(result.fbiu_id,brName);
                                                        Ext.Msg.alert('Notification',result.msg,function (btn) {
                                                            if (btn === 'ok') {
                                                                Ext.Msg.hide();
                                                            }
                                                        });

                                                    } else if (result.valid === false && result.success === true) {
                                                        if (result.error) {
                                                            Ext.Msg.alert('Notification',result.error);
                                                        } else {
                                                            Ext.Msg.alert('Notification','Column in CSV doesnot Match');
                                                        }

                                                    } else {
                                                        if (result.error) {
                                                            Ext.Msg.alert('Notification',result.error);
                                                        }
                                                    }
                                                },
                                                failure: function () {
                                                    Ext.Msg.alert('Error','Supplied CSV File could not be validated. ',function (btn) {
                                                        if (btn === 'ok') {
                                                            Ext.Msg.hide();
                                                            win_csv.close();
                                                        }
                                                    });
                                                }
                                            });
                                        }
                                    }
                                }]
                        }
                    ]
                })
            ]
        });
        win_csv.show();
        win_csv.doLayout();
        win_csv.center();
    };
