    var StateMasterStore = function () {
        var country_id = arguments[0];
        var gridId = arguments[1];
        var _stateMasterStore = new Ext.data.GroupingStore({
            proxy: new Ext.data.HttpProxy({
                url: modURL + '&op=listStates',
                method: 'post'
            }),
            reader: new Ext.data.JsonReader({
                totalProperty: 'totalCount',
                idProperty: 'state_id',
                root: 'data'
            },['state_id','state_name','state_code','status','location']),
            sortInfo: {
                field: 'state_id',
                direction: "DESC"
            },
            groupField: '',
            groupDir: 'ASC',
            remoteSort: true,
            autoLoad: false,
            root: 'data',
            listeners: {
                load: function () {
                    if (gridId == 1)
                    {
                        Ext.getCmp('gridpanelMasterDataviewStatedata').getView().refresh();
                        Ext.getCmp('gridpanelMasterDataviewStatedata').getSelectionModel().selectRow(0);
                    }
                    else
                    {
                        Ext.getCmp('gridpanelBrmLocationDataviewStatedata').getView().refresh();
                        Ext.getCmp('gridpanelBrmLocationDataviewStatedata').getSelectionModel().selectRow(0);
                    }
                }
            },
            baseParams: {
                country_id: country_id
            }

        });

        return _stateMasterStore;
    };

    var StateMainGrid = function () {
        var country_id = arguments[0];
        var gridId = arguments[1];
        var _stateStore = StateMasterStore(country_id,gridId);
        var _stateGridFilter = new Ext.ux.grid.GridFilters({
            filters: [{
                    type: 'string',
                    dataIndex: 'state_name'

                },{
                    type: 'string',
                    dataIndex: 'state_code'
                },{
                    type: 'string',
                    dataIndex: 'status'
                },{
                    type: 'list',
                    options: ['Active','Inactive'],
                    phpMode: true,
                    dataIndex: 'status'
                }]
        });
        _stateGridFilter.remote = true;
        _stateGridFilter.autoReload = true;
        var _statemaingridPanel = new Ext.grid.GridPanel({
            region: 'center',
            layout: 'fit',
            frame: false,
            border: false,
            loadMask: true,
            store: _stateStore,
            //iconCls: 'money',
            id: 'gridpanelMasterDataviewStatedata',
            view: new Ext.grid.GroupingView({
                forceFit: true,
                deferEmptyText: false,
                emptyText: '<div class="grid-data-empty"><div data-icon="/" class="empty-grid-icon"></div><div class="empty-grid-headline"></div><div class="empty-grid-byline">There are no records to show you right now.</div></div>',
                groupTextTpl: '{text} ({[values.rs.length]} {[values.rs.length > 1 ? "Items" : "Item"]})'
            }),
            plugins: [new Ext.ux.grid.GroupSummary(),_stateGridFilter],
            columns: [new Ext.grid.RowNumberer(),
                {
                    header: 'State Name',
                    dataIndex: 'state_name',
                    sortable: true,
                    tooltip: 'State Name',
                    hideable: false
                },
                {
                    header: 'State Code',
                    dataIndex: 'state_code',
                    sortable: true,
                    tooltip: 'State Code',
                    hideable: false
                },
                {
                    header: 'No. of Districts',
                    dataIndex: 'location',
                    sortable: true,
                    tooltip: 'No. of Districts',
                    hideable: false
                },
                {
                    header: 'status',
                    dataIndex: 'status',
                    sortable: true,
                    tooltip: 'Status'
                }
            ],
            viewConfig: {
                forceFit: true
            },
            bbar: new Ext.PagingToolbar({
                pageSize: RECS_PER_PAGE,
                store: _stateStore,
                displayInfo: true,
                displayMsg: 'Displaying records {0} - {1} of {2}',
                emptyMsg: "No pages to display"
            }),
            sm: new Ext.grid.RowSelectionModel({
                singleSelect: true,
                listeners: {
                    selectionchange: gridSelectionChangedstates
                }
            }),
            listeners: {
                cellClick: function (grid,rowIndex,columnIndex,e) {
                    var record = grid.getStore().getAt(rowIndex);

                    Ext.getCmp('textfieldstateid').setValue(record.data.state_id);

                    var ID = record.get('state_id');
                    if (!Ext.isEmpty(ID)) {
                        Application.MyphaLocations.Cache.state_id = ID;
                        Ext.getCmp('formpanelMasterState').hide();
                        Application.MyphaLocations.ViewStates(ID);
                    }

                },
                resize: onGridResize,
                afterrender: function () {
                    _stateStore.load();
                    if (_stateStore.getCount() == 0)
                    {
                        Ext.getCmp('buttonMasterStateEdit').hide();
                    }

                }
            },
            tbar: [{
                    text: 'Add New',
                    tooltip: 'Add New ',
                    icon: './resources/images/default/icons/add.png',
                    iconCls: 'my-icon1',
                    handler: function () {
                        Application.MyphaLocations.StateAddEdit = 'Add';
                        var stateForm = Ext.getCmp('formpanelMasterState').getForm();
                        Ext.getCmp('panelMasterStateParent').setTitle('Add State Details');
                        loadedForm = null;
                        stateForm.reset();
                        Ext.getCmp('state_name').focus(false,100);
                        Ext.getCmp('buttonMasterStateEdit').hide();
                        Ext.getCmp('buttonMasterStateSave').show();
                        Ext.getCmp('buttonMasterStateCancel').show();
                        Ext.getCmp('formpanelMasterState').show();
                        Ext.getCmp('comboMasterStateStatus').setValue(1);
                        Ext.getCmp('panelMasterStateDetailsView').hide();
                        Ext.getCmp('panelMasterStateParent').doLayout();
                    }
                }]
        });
        return _statemaingridPanel;
    };



